using System.Collections.Generic;
using System.Text.RegularExpressions;
using UnityEngine;

namespace Cogworks.View
{
    /// <summary>
    /// Authored sprites from Resources/Art (generated by Tools/art/generate.py). Each entry is a list of
    /// frames named name_0..name_N plus an animation speed, as listed in Art/manifest.json.
    /// Returns null for anything missing so callers can fall back to generated placeholder art.
    /// </summary>
    public static class ArtLibrary
    {
        struct Entry
        {
            public int Frames;
            public int Fps;
        }

        static Dictionary<string, Entry> _manifest;
        static readonly Dictionary<string, Sprite[]> Cache = new Dictionary<string, Sprite[]>();

        static Dictionary<string, Entry> Manifest
        {
            get
            {
                if (_manifest != null) return _manifest;
                _manifest = new Dictionary<string, Entry>();
                var text = Resources.Load<TextAsset>("Art/manifest");
                if (text == null) return _manifest;
                // {"name": {"fps": 8, "frames": 4}, ...}  (keys sorted, so fps precedes frames)
                foreach (Match m in Regex.Matches(text.text, "\"([a-z0-9_]+)\"\\s*:\\s*\\{\\s*\"fps\"\\s*:\\s*(\\d+)\\s*,\\s*\"frames\"\\s*:\\s*(\\d+)"))
                    _manifest[m.Groups[1].Value] = new Entry { Fps = int.Parse(m.Groups[2].Value), Frames = int.Parse(m.Groups[3].Value) };
                return _manifest;
            }
        }

        public static bool Has(string name) => Manifest.ContainsKey(name);

        public static int Fps(string name) => Manifest.TryGetValue(name, out var e) ? e.Fps : 0;

        /// <summary>All frames, or null if the sprite isn't in the library.</summary>
        public static Sprite[] Frames(string name)
        {
            if (Cache.TryGetValue(name, out var frames)) return frames;
            if (Manifest.TryGetValue(name, out var e))
            {
                frames = new Sprite[e.Frames];
                for (int i = 0; i < e.Frames; i++)
                {
                    frames[i] = Resources.Load<Sprite>($"Art/{name}_{i}");
                    if (frames[i] == null)
                    {
                        frames = null;
                        break;
                    }
                }
            }
            Cache[name] = frames;
            return frames;
        }

        public static Sprite First(string name) => Frames(name)?[0];
    }
}
